package com.silverguardian.prototype.modules;
import com.silverguardian.prototype.data.Repository;import com.silverguardian.prototype.models.*;import java.util.*;
public class UserSessionModule{private final Repository r;public UserSessionModule(Repository r){this.r=r;}public List<User>getUsers(){return new ArrayList<>(r.getUsers());}public User addUser(String n,String p,int a,String c){return r.addUser(n,p,a,c);}public User addUser(String n,String p,int a,String c,String q,String ans){return r.addUser(n,p,a,c,q,ans);}public void deleteUser(User u){r.deleteUser(u);}public void setActiveUser(int id){r.setActiveUser(id);}public int getActiveUserId(){return r.getActiveUserId();}public User getActiveUser(){for(User u:r.getUsers())if(u.id==r.getActiveUserId())return u;return r.getUsers().isEmpty()?null:r.getUsers().get(0);}public List<FamilyMember>getFamilyMembers(){return new ArrayList<>(r.getFamilyMembers());}public String findPrimaryFamilyPhone(){for(FamilyMember f:r.getFamilyMembers())if(f.phone!=null&&!f.phone.isEmpty())return f.phone;return null;}}